        JSONArray buildSeasons(JSONArray eps){
            java.util.TreeMap<Integer,Integer> counts=new java.util.TreeMap<>();
            for(int i=0;i<eps.length();i++){JSONObject e=eps.optJSONObject(i);if(e==null)continue;int s=e.optInt("season_number",-1);if(s<0)continue;counts.put(s,(counts.containsKey(s)?counts.get(s):0)+1);}
            JSONArray out=new JSONArray();
            for(java.util.Map.Entry<Integer,Integer> en:counts.entrySet()){try{JSONObject x=new JSONObject();int s=en.getKey();x.put("id","season:"+s);x.put("type","Season");x.put("season_number",s);x.put("name",s==0?"Specials":"Season "+s);x.put("episode_count",en.getValue());out.put(x);}catch(Exception ignore){}}
            return out;
        }
        JSONArray episodesForSeason(int season){
            JSONArray out=new JSONArray();
            for(int i=0;i<libraryEpisodes.length();i++){JSONObject e=libraryEpisodes.optJSONObject(i);if(e!=null&&e.optInt("season_number",-1)==season)out.put(e);}
            return out;
        }
